def choose_move(observation):
    o = observation if isinstance(observation, dict) else {}

    def as_pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except Exception:
                return default
        return default

    def to_points(v):
        pts = []
        if isinstance(v, dict):
            for val in v.values():
                pts.extend(to_points(val))
        elif isinstance(v, (list, tuple)):
            if len(v) >= 2 and not isinstance(v[0], (list, tuple, dict)):
                try:
                    pts.append((int(v[0]), int(v[1])))
                except Exception:
                    pass
            else:
                for item in v:
                    pts.extend(to_points(item))
        return pts

    def clamp_dir(d):
        return -1 if d < -0.5 else (1 if d > 0.5 else 0)

    w = int(o.get("grid_width", o.get("width", 0)) or 0)
    h = int(o.get("grid_height", o.get("height", 0)) or 0)

    sx, sy = as_pair(o.get("self_position", o.get("position", o.get("self", (0, 0)))))
    op = o.get("opponent_position", o.get("enemy_position", o.get("opponent", (0, 0))))
    ox, oy = as_pair(op, (sx, sy))

    blocked = set()
    for key in ("obstacles", "walls", "blocked", "rocks", "hazards"):
        for p in to_points(o.get(key, [])):
            blocked.add(p)

    # Resource / objective targets from multiple possible field names.
    target_points = []
    for key in (
        "resources", "resource_positions", "targets", "objectives", "goals",
        "territories", "zones", "capture_points", "bases", "flags", "items",
        "coins", "pellets", "food"
    ):
        target_points.extend(to_points(o.get(key, [])))

    # Prefer nearest objective, but if none exist, infer from opponent.
    target = None
    best = None
    for x, y in target_points:
        d = abs(x - sx) + abs(y - sy)
        if best is None or d < best or (d == best and (x, y) < target):
            best = d
            target = (x, y)

    # Pursuit/evasion fallback: move away if close, otherwise toward opponent if it seems useful.
    dist_opp = abs(ox - sx) + abs(oy - sy)
    mode_flee = False
    if target is None:
        mode_flee = dist_opp <= 3 and (sx, sy) != (ox, oy)
        if mode_flee:
            target = (sx + (sx - ox), sy + (sy - oy))
        else:
            target = (ox, oy)

    dx = clamp_dir(target[0] - sx)
    dy = clamp_dir(target[1] - sy)

    # Try strong primary move, then axis-separated alternatives, then basic motion.
    candidates = [
        (dx, dy),
        (dx, 0),
        (0, dy),
        (clamp_dir(sx - ox), clamp_dir(sy - oy)) if mode_flee else (0, 0),
        (1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)
    ]

    seen = set()
    for a, b in candidates:
        if (a, b) in seen:
            continue
        seen.add((a, b))
        nx, ny = sx + a, sy + b
        if (w <= 0 or 0 <= nx < w) and (h <= 0 or 0 <= ny < h) and (nx, ny) not in blocked:
            return [a, b]

    return [0, 0]

